// Native and WebXR materials share a single albedo treatment. Only materials
// generated by Atrium are adjusted; authored scan textures/colors are preserved.
const diffuseRanges = {
  marble: [0.44, 0.5], plaster: [0.48, 0.56], limestone: [0.46, 0.56],
  stone: [0.25, 0.4], neutral: [0.34, 0.48],
  'bronze-patina': [0.15, 0.26], wood: [0.14, 0.24], ceramic: [0.18, 0.32],
};
export function rememberSpatialAppearance(material, appearance) {
  material.userData.atriumGeneratedAppearance = {
    key: appearance.key || 'neutral', baseColor: appearance.baseColor,
    roughness: appearance.roughness, metalness: appearance.metalness,
  };
}
export function spatialPaletteColor(THREE, appearance) {
  const color = new THREE.Color(appearance.baseColor);
  const range = diffuseRanges[appearance.key];
  if (range) {
    const luminance = 0.2126 * color.r + 0.7152 * color.g + 0.0722 * color.b;
    if (luminance > 0) color.multiplyScalar(Math.max(range[0], Math.min(range[1], luminance)) / luminance);
  }
  const peak = Math.max(color.r, color.g, color.b);
  if (peak > 0.8) color.multiplyScalar(0.8 / peak);
  return color;
}
export function prepareSpatialSurface(THREE, source, geometry, { native = false } = {}) {
  const material = source.clone();
  const generated = source.userData.atriumGeneratedAppearance;
  let colored = Boolean(source.vertexColors && geometry.hasAttribute('color') && !source.map);
  if (generated && !source.map) {
    const base = new THREE.Color(geometry.userData.atriumPaletteBase || generated.baseColor);
    const target = spatialPaletteColor(THREE, generated);
    material.color.copy(target);
    material.roughness = Math.max(0.48, Math.min(0.85, generated.roughness ?? 0.65));
    material.metalness = generated.metalness ?? 0;
    material.envMapIntensity = 1;
    material.emissive.setRGB(0, 0, 0);
    material.emissiveIntensity = 0;
    if (native) {
      // Quick Look can lose the custom displayColor shader connection and show
      // its gray fallback. Put generated stone/bronze palettes directly in the
      // standard surface material. Keep normals and physical material shading;
      // procedural vertex patina remains in the page and WebXR only.
      material.vertexColors = false;
      geometry.deleteAttribute('color');
      colored = false;
    }
    if (colored) {
      const colors = geometry.getAttribute('color');
      // The existing vertex colors contain the palette already. Transfer their
      // subtle variation to the AR palette without multiplying the page tint.
      for (let i = 0; i < colors.count; i++) {
        colors.setXYZ(i,
          base.r > 1e-6 ? colors.getX(i) * target.r / base.r : target.r,
          base.g > 1e-6 ? colors.getY(i) * target.g / base.g : target.g,
          base.b > 1e-6 ? colors.getZ(i) * target.b / base.b : target.b);
      }
      material.color.setRGB(1, 1, 1);
    }
  }
  return { material, colored, generated: Boolean(generated && !source.map) };
}

export function startSpatialAppearance(THREE, model, scene, renderer) {
  const originals = [], lights = [], preparedMaterials = new Set();
  const saved = { exposure: renderer.toneMappingExposure, toneMapping: renderer.toneMapping, environmentIntensity: scene.environmentIntensity };
  const rig = new THREE.Group(); rig.name = 'Atrium spatial lighting';
  let disposed = false;
  const restore = () => {
    if (disposed) return; disposed = true;
    for (const [mesh, geometry, material] of originals) {
      if (mesh.geometry !== geometry) mesh.geometry.dispose();

      mesh.geometry = geometry; mesh.material = material;
    }
    for (const material of preparedMaterials) material.dispose();
    for (const [light, visible] of lights) light.visible = visible;
    scene.remove(rig);
    renderer.toneMappingExposure = saved.exposure; renderer.toneMapping = saved.toneMapping;
    scene.environmentIntensity = saved.environmentIntensity;
  };
  try {
    model.traverse(mesh => {
      if (!mesh.isMesh) return;
      originals.push([mesh, mesh.geometry, mesh.material]);
      mesh.geometry = mesh.geometry.clone();
      // Multi-material shared colors must not be rewritten repeatedly. Use the
      // palette as a material multiplier over the existing vertex color there.
      const sources = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
      const prepared = sources.map(source => {
        if (sources.length === 1) {
          const material = prepareSpatialSurface(THREE, source, mesh.geometry).material;
          preparedMaterials.add(material);
          return material;
        }
        const temporary = mesh.geometry.clone();
        const result = prepareSpatialSurface(THREE, source, temporary);
        preparedMaterials.add(result.material);
        temporary.dispose();
        if (result.colored && result.generated) {
          const base = new THREE.Color(mesh.geometry.userData.atriumPaletteBase || source.userData.atriumGeneratedAppearance.baseColor);
          const target = spatialPaletteColor(THREE, source.userData.atriumGeneratedAppearance);
          result.material.color.setRGB(base.r > 1e-6 ? target.r / base.r : 1, base.g > 1e-6 ? target.g / base.g : 1, base.b > 1e-6 ? target.b / base.b : 1);
        }
        return result.material;
      });
      mesh.material = Array.isArray(mesh.material) ? prepared : prepared[0];
    });
    scene.traverse(object => { if (object.isLight) { lights.push([object, object.visible]); object.visible = false; } });
    rig.add(new THREE.HemisphereLight(0xf5f3ed, 0x525760, 0.4));
    const key = new THREE.DirectionalLight(0xfff4e6, 2.4); key.position.set(3, 5, 4); rig.add(key);
    const fill = new THREE.DirectionalLight(0xe7edf5, 0.35); fill.position.set(-4, 2, 1); rig.add(fill);
    scene.add(rig);
    scene.environmentIntensity = 0.35;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 0.72;
    return restore;
  } catch (error) { restore(); throw error; }
}
